-- T&A master data -> live (apparel_pulse). Generated from local ie_uat on 2026-11-21.
--
-- RUN ORDER: 1) back up (see below)  2) `php artisan migrate` on live  3) this script.
--
-- Backup first:
--   mysqldump apparel_pulse designations ta_template_actions style_ta_actions > ta_backup_$(date +%F).sql
--
-- Safe to re-run. Nothing here uses local ids: designations are matched by code/name and template
-- rows by (phase, name), because ids differ between databases. It never deletes anything.
-- Style-level actions (style_ta_actions) are NOT copied: locally they exist only on demo styles.

START TRANSACTION;

-- ---------------------------------------------------------------------------------------------
-- 0. Preflight: the migrations must already have run.
-- ---------------------------------------------------------------------------------------------
SELECT COUNT(*) AS ta_template_actions_before FROM ta_template_actions;   -- fails here if not migrated

-- ---------------------------------------------------------------------------------------------
-- 1. Designations used by the T&A master. Created only if neither the code nor the name exists.
--    department_id is looked up by department NAME on live (NULL if live has no such department).
-- ---------------------------------------------------------------------------------------------

-- ---------------------------------------------------------------------------------------------
-- 2. Template actions: insert new, update existing (matched on phase + name).
-- ---------------------------------------------------------------------------------------------

-- ---------------------------------------------------------------------------------------------
-- 3. Verification. Review before COMMIT.
-- ---------------------------------------------------------------------------------------------
SELECT phase, COUNT(*) AS actions, SUM(designation_id IS NULL) AS unmapped, SUM(is_active = 0) AS inactive
  FROM ta_template_actions GROUP BY phase;                                -- expect Development 36 / Plant QCO 34, unmapped 0

-- Rows on live that are not in the local list (e.g. a seed row renamed locally). Not deleted; decide by hand.
SELECT id, phase, sequence, name FROM ta_template_actions WHERE created_at < NOW() - INTERVAL 1 MINUTE AND designation_id IS NULL;

-- Designations whose department could not be matched on live (department_id NULL) — set it in the UI if wanted.
SELECT id, name, code FROM designations WHERE code IN (
'MANAGER-RMWH', 'AM-GARMENT-TECH', 'PE-TECHNICAL', 'PDC-CUTTING-LEAD', 'PDC-EMBELLISHMENT', 'MANAGER-TEC-PD-PE', 'MANAGER-TEC-PLANT', 'CUTTING-MANAGER', 'MANAGER-OPERATION', 'TECHNICAL-MANAGER', 'QCO-IE', 'PLANT-ENGINEER', 'IE-MANAGER', 'QUALITY-MANAGER'
) AND department_id IS NULL;

-- If every number above looks right:  COMMIT;   Otherwise:  ROLLBACK;
